static Sdb *get_verneed_entry_sdb(ELFOBJ *bin, Elf_(Verneed) verneed_entry, size_t offset) { /* <=== get_verneed_entry_sdb */ 
	Sdb *sdb_version = get_verneed_entry_sdb_aux(bin, verneed_entry, offset);
	if (!sdb_version) {
		return NULL;
	}

	ut64 vernaux_entry_offset = offset + verneed_entry.vn_aux;

	for (size_t i = 0; i < verneed_entry.vn_cnt; i++) {
		Elf_(Vernaux) vernaux_entry;
		if (!get_vernaux_entry(bin, vernaux_entry_offset, &vernaux_entry)) {
			sdb_free(sdb_version);
			return NULL;
		}

		Sdb *sdb_vernaux = get_vernaux_entry_sdb(bin, vernaux_entry, vernaux_entry_offset);
		if (!sdb_vernaux) {
			sdb_free(sdb_version);
			return NULL;
		}

		char key[32];
		if (!sdb_ns_set(sdb_version, rz_strf(key, "vernaux%zu", i), sdb_vernaux)) {
			sdb_free(sdb_vernaux);
			sdb_free(sdb_version);
			return NULL;
		}

		sdb_free(sdb_vernaux);

		vernaux_entry_offset += vernaux_entry.vna_next;
	}

	return sdb_version;
}

RZ_API void sdb_ns_free_all(Sdb *s) { /* <=== sdb_ns_free_all */ 
	SdbList *list;
	if (!s) {
		return;
	}
	list = ls_new();
	list->free = NULL;
	ns_free_exc_list(s, list);
	ls_free(list);
	ls_free(s->ns);
	s->ns = NULL;
}

RZ_API int sdb_ns_set(Sdb *s, const char *name, Sdb *r) { /* <=== sdb_ns_set */ 
	SdbNs *ns;
	SdbListIter *it;
	ut32 hash = sdb_hash(name);
	if (!s || !r || !name) {
		return 0;
	}
	ls_foreach (s->ns, it, ns) {
		if (ns->hash == hash) {
			if (ns->sdb == r) {
				return 0;
			}
			sdb_free(ns->sdb);
			r->refs++; // sdb_ref / sdb_unref //
			ns->sdb = r;
			return 1;
		}
	}
	if (s->ns_lock) {
		return 0;
	}
	ns = RZ_NEW(SdbNs);
	ns->name = strdup(name);
	ns->hash = hash;
	ns->sdb = r;
	r->refs++;
	ls_append(s->ns, ns);
	return 1;
}

static void sdb_fini(Sdb *s, int donull) { /* <=== sdb_fini */ 
	if (!s) {
		return;
	}
	sdb_hook_free(s);
	cdb_free(&s->db);
	if (s->lock) {
		sdb_unlock(sdb_lock_file(s->dir));
	}
	sdb_ns_free_all(s);
	s->refs = 0;
	free(s->name);
	free(s->path);
	ls_free(s->ns);
	sdb_ht_free(s->ht);
	sdb_journal_close(s);
	if (s->fd != -1) {
		close(s->fd);
		s->fd = -1;
	}
	free(s->ndump);
	free(s->dir);
	if (donull) {
		memset(s, 0, sizeof(Sdb));
	}
}

RZ_API int sdb_num_set(Sdb *s, const char *key, ut64 v, ut32 cas) { /* <=== sdb_num_set */ 
	char *val, b[SDB_NUM_BUFSZ];
	int numbase = sdb_num_base(sdb_const_get(s, key, NULL));
	val = sdb_itoa(v, b, numbase);
	return sdb_set(s, key, val, cas);
}

