		return NULL;
	}

	return sdb_version;
}

static ut32 sdb_set_internal(Sdb *s, const char *key, char *val, int owned, ut32 cas) { /* <=== sdb_set_internal */ 
	ut32 vlen, klen;
	SdbKv *kv;
	bool found;
	if (!s || !key) {
		return 0;
	}
	if (!val) {
		if (owned) {
			val = strdup("");
		} else {
			val = "";
		}
	}
	// XXX strlen computed twice.. because of check_*()
	klen = strlen(key);
	vlen = strlen(val);
	if (s->journal != -1) {
		sdb_journal_log(s, key, val);
	}
	cdb_findstart(&s->db);
	kv = sdb_ht_find_kvp(s->ht, key, &found);
	if (found && sdbkv_value(kv)) {
		if (cdb_findnext(&s->db, sdb_hash(key), key, klen)) {
			if (cas && kv->cas != cas) {
				if (owned) {
					free(val);
				}
				return 0;
			}
			if (vlen == sdbkv_value_len(kv) && !strcmp(sdbkv_value(kv), val)) {
				sdb_hook_call(s, key, val);
				return kv->cas;
			}
			kv->cas = cas = nextcas();
			if (owned) {
				kv->base.value_len = vlen;
				free(kv->base.value);
				kv->base.value = val; // owned
			} else {
				if ((ut32)vlen > kv->base.value_len) {
					free(kv->base.value);
					kv->base.value = malloc(vlen + 1);
				}
				memcpy(kv->base.value, val, vlen + 1);
				kv->base.value_len = vlen;
			}
		} else {
			sdb_ht_delete(s->ht, key);
		}
		sdb_hook_call(s, key, val);
		return cas;
	}
	// empty values are also stored
	// TODO store only the ones that are in the CDB
	if (owned) {
		kv = sdbkv_new2(key, klen, NULL, 0);
		if (kv) {
			kv->base.value = val;
			kv->base.value_len = vlen;
		}
	} else {
		kv = sdbkv_new2(key, klen, val, vlen);
	}
	if (kv) {
		ut32 cas = kv->cas = nextcas();
		sdb_ht_insert_kvp(s->ht, kv, true /*update*/);
		free(kv);
		sdb_hook_call(s, key, val);
		return cas;
	}
	// kv set failed, no need to callback	sdb_hook_call (s, key, val);
	return 0;
}

static Sdb *get_vernaux_entry_sdb(ELFOBJ *bin, Elf_(Vernaux) vernaux_entry, size_t index) { /* <=== get_vernaux_entry_sdb */ 
	const char *tmp = Elf_(rz_bin_elf_strtab_get)(bin->dynstr, vernaux_entry.vna_name);
	if (!tmp) {
		return NULL;
	}

	Sdb *sdb_vernaux = sdb_new0();
	if (!sdb_vernaux) {
		return NULL;
	}

	char *flags = get_ver_flags(vernaux_entry.vna_flags);
	if (!sdb_set_owned(sdb_vernaux, "flags", flags, 0)) {
		sdb_free(sdb_vernaux);
		return NULL;
	}

	if (!sdb_num_set(sdb_vernaux, "idx", index, 0) ||
		!sdb_num_set(sdb_vernaux, "version", vernaux_entry.vna_other, 0) ||
		!sdb_set(sdb_vernaux, "name", tmp, 0)) {
		sdb_free(sdb_vernaux);
		return NULL;
	}

	return sdb_vernaux;
}

